/*
 * DSi RA Bridge 0.4.6 — offline host experiment using REAL pinned rcheevos.
 * Inputs are synthetic CSV values generated by frame-bridge-046.py, not a
 * Nintendo DS game or official RetroAchievements triggers. No HTTP, login,
 * account, hardware, awards, memory writes to another process, or ROM.
 *
 * Compiles against the existing project pin of skierrz/rcheevos:
 *   754965ef28db22b0411bfccbde39154cd09e6b79
 * The trigger strings below are deliberately invented LOCAL QA predicates.
 */
#include "rc_runtime.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MEMORY_SIZE 512u
#define STAR_ID 46001u
#define COIN_ID 46002u
#define NEVER_ID 46003u
#define STRESS_FRAMES 60000u

static uint8_t g_memory[MEMORY_SIZE];
static unsigned g_stars_triggered;
static unsigned g_coins_triggered;
static unsigned g_never_triggered;
static unsigned long g_reads;

static uint32_t read_memory(uint32_t address, uint8_t* dest, uint32_t len, void* unused) {
  (void)unused;
  if (address > MEMORY_SIZE || len > MEMORY_SIZE - address)
    return 0;
  memcpy(dest, g_memory + address, len);
  ++g_reads;
  return len;
}

static void on_event(const rc_runtime_event_t* event) {
  if (event->type != RC_RUNTIME_EVENT_ACHIEVEMENT_TRIGGERED)
    return;
  if (event->id == STAR_ID)
    ++g_stars_triggered;
  else if (event->id == COIN_ID)
    ++g_coins_triggered;
  else if (event->id == NEVER_ID)
    ++g_never_triggered;
}

static void fail(const char* why) {
  fprintf(stderr, "RCHEEVOS_046_SYNTHETIC_FAILURE: %s\n", why);
  exit(2);
}

int main(int argc, char** argv) {
  rc_runtime_t runtime;
  FILE* file;
  char line[128];
  unsigned frame, stars, coins, next_expected = 0, frames = 0, i;
  clock_t begin, end;
  double cpu_ms;
  if (argc != 2)
    fail("usage: ra-runtime-smoke-046 synthetic-trace-046.csv");
  file = fopen(argv[1], "r");
  if (!file)
    fail("synthetic trace missing");
  if (!fgets(line, sizeof(line), file) ||
      strcmp(line, "frame,stars_synthetic,coins_synthetic\n") != 0)
    fail("unexpected trace header");
  memset(g_memory, 0, sizeof(g_memory));
  rc_runtime_init(&runtime);
  if (rc_runtime_activate_achievement(&runtime, STAR_ID, "0xH000100=1", NULL, 0) != 0 ||
      rc_runtime_activate_achievement(&runtime, COIN_ID, "0xH000101=3", NULL, 0) != 0 ||
      rc_runtime_activate_achievement(&runtime, NEVER_ID, "0xH000102=55", NULL, 0) != 0)
    fail("cannot activate fabricated triggers on pinned rcheevos");

  while (fgets(line, sizeof(line), file)) {
    int consumed = 0;
    if (sscanf(line, "%u,%u,%u%n", &frame, &stars, &coins, &consumed) != 3 ||
        !consumed || (line[consumed] != '\r' && line[consumed] != '\n' && line[consumed] != '\0'))
      fail("bad synthetic CSV row");
    if (frame != next_expected++ || stars > 1 || coins > 3)
      fail("bad synthetic frame sequence or value");
    g_memory[0x100] = (uint8_t)stars;
    g_memory[0x101] = (uint8_t)coins;
    rc_runtime_do_frame(&runtime, on_event, read_memory, NULL, NULL);
    ++frames;
  }
  fclose(file);
  if (frames != 5 || g_stars_triggered != 1 || g_coins_triggered != 1 ||
      g_never_triggered != 0 || g_reads < 5)
    fail("expected exact synthetic star and coin triggers not observed");

  /* Deterministic host CPU stress only. NOT a 60Hz timing claim on DSi. */
  begin = clock();
  for (i = 0; i < STRESS_FRAMES; ++i) {
    g_memory[0x102] = (uint8_t)(i & 1u);
    rc_runtime_do_frame(&runtime, on_event, read_memory, NULL, NULL);
  }
  end = clock();
  if (g_never_triggered || g_stars_triggered != 1 || g_coins_triggered != 1)
    fail("unexpected trigger during synthetic stress");
  cpu_ms = 1000.0 * (double)(end - begin) / (double)CLOCKS_PER_SEC;
  printf("RCHEEVOS_046_SYNTHETIC_RUNTIME_PASS frames=%u "
         "star_triggers=%u coin_triggers=%u stress_frames=%u "
         "read_callbacks=%lu host_cpu_ms=%.3f "
         "hardware=NOT_RUN official_awards=NO\n",
         frames, g_stars_triggered, g_coins_triggered, STRESS_FRAMES,
         g_reads, cpu_ms);
  rc_runtime_destroy(&runtime);
  return 0;
}
